mapper.select:
SELECT c.asset_id, c.source_version, c.paragraph_no, c.start_offset, c.content, a.asset_name, a.asset_type, ( (CASE WHEN LOCATE(#{term}, LOWER(c.content)) > 0 THEN 2 ELSE 0 END + CASE WHEN LOCATE(#{term}, LOWER(a.asset_name)) > 0 THEN 4 ELSE 0 END + CASE WHEN LOCATE(#{term}, LOWER(a.domain_name)) > 0 THEN 2 ELSE 0 END + CASE WHEN LOCATE(#{term}, LOWER(a.description)) > 0 THEN 1 ELSE 0 END) ) AS match_score FROM wiki_asset_chunk c JOIN wiki_asset a ON a.asset_id = c.asset_id WHERE a.status = '0' AND COALESCE(a.tags, '') <> 'SYSTEM_INDEX' AND (a.space_id IS NULL OR EXISTS (SELECT 1 FROM wiki_space s WHERE s.space_id = a.space_id AND s.status = '0')) AND ( (LOCATE(#{term}, LOWER(c.content)) > 0 OR LOCATE(#{term}, LOWER(a.asset_name)) > 0 OR LOCATE(#{term}, LOWER(a.domain_name)) > 0 OR LOCATE(#{term}, LOWER(a.description)) > 0) ) AND a.space_id = #{spaceId}
AND a.asset_type IN #{assetType}
AND (a.asset_id = #{scopeId} OR a.tags = CONCAT('SOURCE:', #{scopeId})) AND EXISTS (SELECT 1 FROM wiki_asset root WHERE root.asset_id = #{scopeId} AND root.status = '0' AND (root.space_id = a.space_id OR (root.space_id IS NULL AND a.space_id IS NULL)))
AND a.asset_type <> 'URL'
ORDER BY match_score DESC, c.asset_id DESC, c.chunk_index ASC LIMIT #{limit}
